css:
/* =========================================================
   PAGE RESET / HIDE DEFAULT FRAPPE WEBSITE ELEMENTS
========================================================= */

html,
body {
    margin: 0 !important;
    padding: 0 !important;
    width: 100% !important;
    min-height: 100% !important;
    background: #f3f0e8 !important;
    overflow-x: hidden !important;
}


/* Hide default website navbar/footer */
.navbar,
.navbar-light,
.navbar-expand-lg,
.website-navbar,
header.navbar,
.website-footer,
.web-footer,
footer,
.page-footer,
.page-header,
.page-title,
.page-breadcrumbs,
.breadcrumbs {
    display: none !important;
}


/* Remove default page spacing */
main,
.main-section,
.hero-and-content,
.page-content-wrapper,
.page_content,
.web-page-content {
    width: 100% !important;
    max-width: 100% !important;
    margin: 0 !important;
    padding: 0 !important;
}


/* Full width container */
.container,
.container-fluid,
.hero-and-content .container,
.page_content .container,
.web-page-content .container {
    width: 100% !important;
    max-width: 100% !important;
    margin: 0 !important;
    padding-left: 0 !important;
    padding-right: 0 !important;
}


/* Remove unwanted heading/title coming from Web Page */
.hero-and-content h1,
.page_content > h1,
.web-page-content > h1 {
    display: none !important;
}


/* =========================================================
   MAIN APP
========================================================= */

#fad-app {

    --fad-dark-green: #005638;
    --fad-dark-green-2: #064a32;

    --fad-green: #087648;
    --fad-green-hover: #0a8652;

    --fad-green-light: #e7f4ec;
    --fad-green-light-2: #d6ebdf;

    --fad-gold: #b98508;
    --fad-gold-dark: #976e05;

    --fad-bg: #f3f0e8;
    --fad-bg-soft: #f8f6f1;

    --fad-white: #ffffff;

    --fad-text: #163a2d;
    --fad-muted: #6e8177;

    --fad-border: #d9d2c4;

    --fad-shadow:
        0 3px 12px
        rgba(26, 65, 47, 0.08);

    width: 100%;
    min-height: 100vh;

    margin: 0;
    padding: 0;

    background:
        linear-gradient(
            180deg,
            #f7f5ef 0%,
            #efede6 100%
        );

    color: var(--fad-text);

    font-family:
        "DM Sans",
        "Inter",
        "Segoe UI",
        Arial,
        sans-serif;
}


/* universal sizing */
#fad-app *,
#fad-app *::before,
#fad-app *::after {
    box-sizing: border-box;
}


/* =========================================================
   MAIN SHELL
========================================================= */

#fad-app .fad-shell {
    width: 100%;
    min-height: 100vh;

    margin: 0;

    padding:
        16px
        18px
        32px;

    background:
        linear-gradient(
            180deg,
            #f6f4ee 0%,
            #efede6 100%
        );
}


/* =========================================================
   HERO / PAGE TITLE CARD
========================================================= */

#fad-app .fad-hero {

    width: 100%;

    display: flex;
    align-items: center;
    justify-content: space-between;

    gap: 20px;

    padding:
        20px
        22px;

    margin:
        0
        0
        15px;

    background: #ffffff;

    border:
        1px solid
        var(--fad-border);

    border-left:
        5px solid
        var(--fad-green);

    border-radius: 15px;

    box-shadow:
        var(--fad-shadow);
}


#fad-app .fad-hero-left {
    flex: 1;
    min-width: 0;
}


#fad-app .fad-hero-right {
    flex: 0 0 auto;
}


/* DOCUMENT MANAGEMENT */
#fad-app .fad-kicker {

    margin-bottom: 7px;

    color: var(--fad-gold);

    font-size: 11px;

    font-weight: 900;

    letter-spacing: 3px;

    text-transform: uppercase;
}


/* Forms & Documents */
#fad-app .fad-hero-title {

    margin:
        0
        0
        6px;

    padding: 0;

    color: #003d2a;

    font-size: 30px;

    line-height: 1.08;

    font-weight: 900;

    letter-spacing: -0.7px;
}


#fad-app .fad-hero-description {

    max-width: 980px;

    color: var(--fad-muted);

    font-size: 13px;

    line-height: 1.55;
}


/* =========================================================
   ACTIVE TAB COUNT
========================================================= */

#fad-app .fad-total-box {

    min-width: 170px;

    padding:
        13px
        17px;

    text-align: center;

    background:
        linear-gradient(
            180deg,
            #fffdf7 0%,
            #f7f2e5 100%
        );

    border:
        1px solid
        #dbd1bd;

    border-radius: 11px;
}


#fad-app .fad-total-label {

    color: #7c725e;

    font-size: 9px;

    font-weight: 900;

    letter-spacing: 1.5px;

    text-transform: uppercase;
}


#fad-app .fad-total-value {

    margin-top: 5px;

    color: var(--fad-dark-green);

    font-size: 15px;

    font-weight: 900;
}


/* =========================================================
   TABS WRAPPER
========================================================= */

#fad-app .fad-tabs-wrap {

    width: 100%;

    margin-bottom: 15px;

    padding: 7px;

    background: #ffffff;

    border:
        1px solid
        var(--fad-border);

    border-radius: 13px;

    box-shadow:
        var(--fad-shadow);
}


/* =========================================================
   TABS
========================================================= */

#fad-app .fad-tabs {

    display: flex;
    align-items: center;

    gap: 7px;

    width: 100%;

    overflow-x: auto;
    overflow-y: hidden;

    scrollbar-width: thin;

    -webkit-overflow-scrolling:
        touch;
}


#fad-app .fad-tab {

    appearance: none;
    -webkit-appearance: none;

    flex:
        0
        0
        auto;

    min-height: 40px;

    display: inline-flex;
    align-items: center;
    justify-content: center;

    gap: 7px;

    padding:
        9px
        14px;

    border:
        1px solid
        transparent;

    outline: none;

    border-radius: 9px;

    background:
        transparent;

    color: #51695c;

    font-family: inherit;

    font-size: 12px;

    font-weight: 800;

    line-height: 1;

    white-space: nowrap;

    cursor: pointer;

    transition:
        background 0.18s ease,
        color 0.18s ease,
        border-color 0.18s ease,
        box-shadow 0.18s ease,
        transform 0.18s ease;
}


#fad-app .fad-tab:hover {

    color:
        var(--fad-green);

    background:
        #edf7f1;

    border-color:
        #d4e8dc;
}


#fad-app .fad-tab:focus {
    outline: none;
}


/* ACTIVE TAB */
#fad-app .fad-tab.fad-tab-active {

    color: #ffffff;

    background:
        linear-gradient(
            135deg,
            #087648 0%,
            #005638 100%
        );

    border-color:
        transparent;

    box-shadow:
        0 4px 10px
        rgba(0, 85, 52, 0.2);
}


/* tab emoji */
#fad-app .fad-tab-icon {

    display: inline-flex;

    align-items: center;
    justify-content: center;

    font-size: 14px;

    line-height: 1;
}


/* count */
#fad-app .fad-tab-pill {

    min-width: 23px;

    padding:
        2px
        7px;

    text-align: center;

    border-radius: 999px;

    background:
        rgba(
            255,
            255,
            255,
            0.18
        );

    color: inherit;

    font-size: 10px;

    font-weight: 900;

    line-height: 1.3;
}


/* inactive count */
#fad-app
.fad-tab:not(.fad-tab-active)
.fad-tab-pill {

    color:
        var(--fad-green);

    background:
        #e5f2ea;
}


/* =========================================================
   CONTENT
========================================================= */

#fad-app .fad-content {

    width: 100%;

    margin: 0;

    padding: 0;
}


/* =========================================================
   PANELS
========================================================= */

#fad-app .fad-panel {

    display: none;

    width: 100%;
}


#fad-app .fad-panel.fad-panel-active {

    display: block;
}


/* =========================================================
   DOCUMENT GRID
========================================================= */

#fad-app .fad-grid {

    display: grid;

    grid-template-columns:
        repeat(
            auto-fill,
            minmax(
                270px,
                1fr
            )
        );

    gap: 13px;

    width: 100%;
}


/* =========================================================
   DOCUMENT CARD
========================================================= */

#fad-app .fad-card {

    position: relative;

    min-width: 0;

    display: flex;
    align-items: center;

    gap: 13px;

    padding:
        15px
        15px;

    background:
        #ffffff;

    border:
        1px solid
        var(--fad-border);

    border-left:
        4px solid
        var(--fad-green);

    border-radius:
        12px;

    cursor: pointer;

    box-shadow:
        var(--fad-shadow);

    transition:
        transform 0.18s ease,
        box-shadow 0.18s ease,
        border-color 0.18s ease;
}


#fad-app .fad-card:hover {

    transform:
        translateY(-2px);

    border-color:
        #b8cbbf;

    border-left-color:
        var(--fad-green-hover);

    box-shadow:
        0 8px 22px
        rgba(
            16,
            77,
            49,
            0.12
        );
}


/* =========================================================
   CARD ICON
========================================================= */

#fad-app .fad-card-icon {

    width: 46px;
    height: 46px;

    flex:
        0
        0
        46px;

    display: flex;

    align-items: center;
    justify-content: center;

    background:
        linear-gradient(
            135deg,
            #e8f5ed 0%,
            #d5ecdd 100%
        );

    border:
        1px solid
        #d8eadf;

    border-radius:
        10px;

    font-size:
        22px;

    line-height:
        1;
}


/* =========================================================
   CARD CONTENT
========================================================= */

#fad-app .fad-card-body {

    flex: 1;

    min-width: 0;
}


#fad-app .fad-card-title {

    overflow: hidden;

    color:
        #18392c;

    font-size:
        13px;

    font-weight:
        900;

    line-height:
        1.35;

    white-space:
        nowrap;

    text-overflow:
        ellipsis;
}


#fad-app .fad-card-sub {

    margin-top:
        4px;

    overflow: hidden;

    color:
        #809087;

    font-size:
        11px;

    font-weight:
        600;

    line-height:
        1.35;

    white-space:
        nowrap;

    text-overflow:
        ellipsis;
}


/* =========================================================
   CARD ARROW
========================================================= */

#fad-app .fad-card-arrow {

    flex:
        0
        0
        auto;

    color:
        #afbeb5;

    font-size:
        22px;

    font-weight:
        300;

    line-height:
        1;

    transition:
        color 0.18s ease,
        transform 0.18s ease;
}


#fad-app .fad-card:hover
.fad-card-arrow {

    color:
        var(--fad-green);

    transform:
        translateX(3px);
}


/* =========================================================
   DOCUMENT TITLE TOOLTIP
========================================================= */

#fad-app .fad-card::after {

    content:
        attr(data-title);

    position:
        absolute;

    left:
        14px;

    bottom:
        calc(
            100% + 8px
        );

    z-index:
        9999;

    width:
        max-content;

    max-width:
        330px;

    padding:
        8px
        10px;

    background:
        #17392b;

    color:
        #ffffff;

    border-radius:
        8px;

    box-shadow:
        0 8px 22px
        rgba(
            0,
            0,
            0,
            0.2
        );

    font-size:
        11px;

    font-weight:
        600;

    line-height:
        1.4;

    white-space:
        normal;

    opacity:
        0;

    visibility:
        hidden;

    pointer-events:
        none;

    transform:
        translateY(4px);

    transition:
        opacity 0.15s ease,
        visibility 0.15s ease,
        transform 0.15s ease;
}


#fad-app .fad-card:hover::after {

    opacity: 1;

    visibility:
        visible;

    transform:
        translateY(0);
}


/* =========================================================
   LOADING / EMPTY / ERROR
========================================================= */

#fad-app .fad-loading,
#fad-app .fad-empty,
#fad-app .fad-error {

    grid-column:
        1 / -1;

    width: 100%;

    padding:
        38px
        20px;

    text-align:
        center;

    border:
        1px solid
        var(--fad-border);

    border-radius:
        12px;

    background:
        #ffffff;

    box-shadow:
        var(--fad-shadow);

    font-size:
        13px;

    font-weight:
        600;
}


#fad-app .fad-loading {

    color:
        #778a7f;
}


#fad-app .fad-empty {

    color:
        #778a7f;
}


#fad-app .fad-error {

    color:
        #b72c2c;

    background:
        #fff6f6;

    border-color:
        #efcccc;
}


/* =========================================================
   MODAL OVERLAY
========================================================= */

#fad-app .fad-modal-overlay {

    position:
        fixed;

    inset:
        0;

    z-index:
        9999999;

    display:
        none;

    align-items:
        center;

    justify-content:
        center;

    padding:
        20px;

    background:
        rgba(
            8,
            38,
            26,
            0.55
        );

    backdrop-filter:
        blur(3px);

    -webkit-backdrop-filter:
        blur(3px);
}


#fad-app
.fad-modal-overlay.fad-modal-show {

    display:
        flex;
}


/* =========================================================
   MODAL
========================================================= */

#fad-app .fad-modal {

    position:
        relative;

    width:
        100%;

    max-width:
        460px;

    padding:
        30px
        24px
        24px;

    background:
        #ffffff;

    border:
        1px solid
        #d6cec0;

    border-radius:
        16px;

    text-align:
        center;

    box-shadow:
        0 25px 70px
        rgba(
            0,
            0,
            0,
            0.28
        );

    animation:
        fadModalIn
        0.18s
        ease-out;
}


@keyframes fadModalIn {

    from {

        opacity:
            0;

        transform:
            translateY(10px)
            scale(0.98);
    }

    to {

        opacity:
            1;

        transform:
            translateY(0)
            scale(1);
    }

}


/* =========================================================
   MODAL CLOSE
========================================================= */

#fad-app .fad-modal-close {

    position:
        absolute;

    top:
        11px;

    right:
        12px;

    width:
        34px;

    height:
        34px;

    display:
        flex;

    align-items:
        center;

    justify-content:
        center;

    padding:
        0;

    border:
        0;

    border-radius:
        50%;

    outline:
        none;

    background:
        #edf2ee;

    color:
        #52655b;

    font-family:
        inherit;

    font-size:
        23px;

    font-weight:
        400;

    line-height:
        1;

    cursor:
        pointer;
}


#fad-app .fad-modal-close:hover {

    color:
        #17382b;

    background:
        #dfe8e2;
}


/* =========================================================
   MODAL DOCUMENT ICON
========================================================= */

#fad-app .fad-modal-icon {

    width:
        68px;

    height:
        68px;

    display:
        flex;

    align-items:
        center;

    justify-content:
        center;

    margin:
        0
        auto
        16px;

    background:
        linear-gradient(
            135deg,
            #e7f4ec 0%,
            #d4eadc 100%
        );

    border:
        1px solid
        #cee4d6;

    border-radius:
        50%;

    font-size:
        31px;
}


/* =========================================================
   MODAL TITLE
========================================================= */

#fad-app .fad-modal-title {

    color:
        #16382c;

    font-size:
        18px;

    font-weight:
        900;

    line-height:
        1.35;

    word-break:
        break-word;
}


#fad-app .fad-modal-sub {

    margin-top:
        7px;

    color:
        #73857b;

    font-size:
        12px;

    line-height:
        1.5;
}


/* =========================================================
   MODAL BUTTONS
========================================================= */

#fad-app .fad-modal-actions {

    display:
        flex;

    align-items:
        stretch;

    gap:
        11px;

    margin-top:
        23px;
}


#fad-app .fad-action {

    flex:
        1;

    min-height:
        43px;

    display:
        inline-flex;

    align-items:
        center;

    justify-content:
        center;

    gap:
        7px;

    padding:
        11px
        16px;

    border:
        0;

    border-radius:
        10px;

    outline:
        none;

    color:
        #ffffff;

    font-family:
        inherit;

    font-size:
        12px;

    font-weight:
        900;

    line-height:
        1.2;

    cursor:
        pointer;

    transition:
        transform 0.15s ease,
        box-shadow 0.15s ease,
        filter 0.15s ease;
}


#fad-app .fad-action:hover {

    transform:
        translateY(-1px);

    filter:
        brightness(1.03);
}


#fad-app .fad-action:active {

    transform:
        translateY(0);
}


/* Open button */
#fad-app .fad-action-open {

    background:
        linear-gradient(
            135deg,
            #087648 0%,
            #005638 100%
        );

    box-shadow:
        0 4px 10px
        rgba(
            0,
            85,
            52,
            0.18
        );
}


/* Download button */
#fad-app .fad-action-download {

    background:
        linear-gradient(
            135deg,
            #bf8c12 0%,
            #9c7003 100%
        );

    box-shadow:
        0 4px 10px
        rgba(
            156,
            112,
            3,
            0.18
        );
}


/* =========================================================
   SCROLLBAR
========================================================= */

#fad-app .fad-tabs::-webkit-scrollbar {

    height:
        5px;
}


#fad-app .fad-tabs::-webkit-scrollbar-track {

    background:
        transparent;
}


#fad-app .fad-tabs::-webkit-scrollbar-thumb {

    background:
        #c5d3ca;

    border-radius:
        999px;
}


/* =========================================================
   TABLET
========================================================= */

@media (
    max-width:
    900px
) {

    #fad-app .fad-shell {

        padding:
            14px
            14px
            28px;
    }


    #fad-app .fad-hero {

        align-items:
            flex-start;

        padding:
            18px;
    }


    #fad-app .fad-hero-title {

        font-size:
            26px;
    }


    #fad-app .fad-grid {

        grid-template-columns:
            repeat(
                auto-fill,
                minmax(
                    230px,
                    1fr
                )
            );
    }

}


/* =========================================================
   MOBILE
========================================================= */

@media (
    max-width:
    650px
) {

    #fad-app .fad-shell {

        padding:
            12px
            12px
            24px;
    }


    #fad-app .fad-hero {

        flex-direction:
            column;

        align-items:
            stretch;

        gap:
            15px;

        padding:
            17px;

        border-left-width:
            4px;
    }


    #fad-app .fad-hero-title {

        font-size:
            23px;

        letter-spacing:
            -0.3px;
    }


    #fad-app .fad-hero-description {

        font-size:
            12px;
    }


    #fad-app .fad-total-box {

        width:
            100%;

        min-width:
            0;
    }


    #fad-app .fad-tabs-wrap {

        padding:
            6px;
    }


    #fad-app .fad-tab {

        min-height:
            38px;

        padding:
            8px
            11px;

        font-size:
            11px;
    }


    #fad-app .fad-grid {

        grid-template-columns:
            1fr;

        gap:
            10px;
    }


    #fad-app .fad-card {

        padding:
            13px;

        gap:
            11px;
    }


    #fad-app .fad-card-icon {

        width:
            42px;

        height:
            42px;

        flex-basis:
            42px;

        font-size:
            20px;
    }


    #fad-app .fad-modal {

        padding:
            28px
            17px
            18px;
    }


    #fad-app .fad-modal-actions {

        flex-direction:
            column;
    }

}


/* =========================================================
   VERY SMALL DEVICES
========================================================= */

@media (
    max-width:
    380px
) {

    #fad-app .fad-hero-title {

        font-size:
            21px;
    }


    #fad-app .fad-kicker {

        font-size:
            9px;

        letter-spacing:
            2px;
    }


    #fad-app .fad-card-title {

        font-size:
            12px;
    }

}

javascript:
(function () {

    "use strict";


    var app = document.getElementById("fad-app");

    if (!app) {
        ("[Forms & Documents] #fad-app not found", void 0);
        return;
    }


    /* =========================================================
       HELPERS
    ========================================================= */

    function qs(selector) {
        return app.querySelector(selector);
    }


    function qsa(selector) {
        return Array.prototype.slice.call(
            app.querySelectorAll(selector)
        );
    }


    function escapeHtml(value) {

        if (value === null || value === undefined) {
            return "";
        }

        return String(value)
            .replace(/&/g, "&amp;")
            .replace(/</g, "&lt;")
            .replace(/>/g, "&gt;")
            .replace(/"/g, "&quot;")
            .replace(/'/g, "&#039;");
    }


    function escapeAttr(value) {
        return escapeHtml(value).replace(/`/g, "&#096;");
    }


    function formatDateOnly(value) {

        if (!value) {
            return "";
        }

        var raw = String(value);
        var datePart = raw.split(" ")[0].split("T")[0];
        var parts = datePart.split("-");

        if (parts.length !== 3) {
            return raw;
        }

        var year = parts[0];
        var month = parts[1];
        var day = parts[2];

        var months = {
            "01": "Jan",
            "02": "Feb",
            "03": "Mar",
            "04": "Apr",
            "05": "May",
            "06": "Jun",
            "07": "Jul",
            "08": "Aug",
            "09": "Sep",
            "10": "Oct",
            "11": "Nov",
            "12": "Dec"
        };

        return day + "-" + (months[month] || month) + "-" + year;
    }


    function makeAbsoluteUrl(url) {

        if (!url) {
            return "";
        }

        url = String(url).trim();

        if (!url) {
            return "";
        }

        if (
            url.indexOf("http://") === 0 ||
            url.indexOf("https://") === 0
        ) {
            return url;
        }

        if (url.charAt(0) === "/") {
            return window.location.origin + url;
        }

        return window.location.origin + "/" + url;
    }


    function getFilenameFromUrl(url) {

        try {

            var clean = String(url)
                .split("?")[0]
                .split("#")[0];

            var parts = clean.split("/");

            return decodeURIComponent(
                parts[parts.length - 1]
            ) || "document";

        } catch (e) {

            return "document";

        }
    }


