    /* =========================================================
       FRAPPE CALL
    ========================================================= */

    function frappeCall(method, args) {

        return new Promise(
            function (resolve, reject) {

                if (
                    !window.frappe ||
                    typeof frappe.call !== "function"
                ) {

                    reject(
                        new Error(
                            "Frappe API is unavailable"
                        )
                    );

                    return;
                }

                frappe.call({

                    method: method,

                    args: args || {},

                    callback: function (response) {
                        resolve(response);
                    },

                    error: function (error) {
                        reject(error);
                    }

                });

            }
        );
    }


    /* =========================================================
       REPORTVIEW PARSER
    ========================================================= */

    function parseReportViewRows(response) {

        var message =
            response && response.message
                ? response.message
                : {};

        var keys = message.keys || [];
        var values = message.values || [];

        return values.map(function (row) {

            var obj = {};

            keys.forEach(
                function (key, index) {
                    obj[key] = row[index];
                }
            );

            return obj;
        });
    }


    /* =========================================================
       LOAD LIST
    ========================================================= */

    async function getReportViewList(config) {

        var doctype = config.doctype;

        var response = await frappeCall(

            "frappe.desk.reportview.get",

            {
                doctype: doctype,

                fields: [
                    "`tab" + doctype + "`.`name`",
                    "`tab" + doctype + "`.`modified`",
                    "`tab" + doctype + "`.`docstatus`"
                ],

                filters: config.filters || [],

                order_by:
                    "`tab" +
                    doctype +
                    "`.`modified` desc",

                start: 0,

                page_length:
                    config.limit || 200,

                view: "List",

                group_by: null,

                with_comment_count: 0
            }

        );

        return parseReportViewRows(response);
    }


    async function getClientList(config) {

        var response = await frappeCall(

            "frappe.client.get_list",

            {
                doctype: config.doctype,

                fields: [
                    "name",
                    "modified",
                    "docstatus"
                ],

                filters: config.filters || [],

                order_by: "modified desc",

                limit_start: 0,

                limit_page_length:
                    config.limit || 200
