    /* =========================================================
       CHILD ROWS
    ========================================================= */

    function getChildRows(
        doc,
        preferredField
    ) {

        if (!doc) {
            return [];
        }

        var fields = [
            preferredField,
            "forms_and_documents",
            "forms_and_document",
            "documents",
            "document"
        ];

        for (
            var i = 0;
            i < fields.length;
            i++
        ) {

            var field = fields[i];

            if (
                field &&
                Array.isArray(doc[field])
            ) {
                return doc[field];
            }
        }

        return [];
    }


    /* =========================================================
       FILE URL
    ========================================================= */

    function getRowFileUrl(row) {

        if (!row) {
            return "";
        }

        var possible = [
            row.files,
            row.file,
            row.file_url,
            row.attachment,
            row.attach,
            row.document,
            row.document_file,
            row.attach_file
        ];

        for (
            var i = 0;
            i < possible.length;
            i++
        ) {

            if (possible[i]) {
                return possible[i];
            }
        }

        return "";
    }


    /* =========================================================
       TITLE
    ========================================================= */

    function getDocumentTitle(
        doc,
        config,
        item
    ) {

        var fields = [
            config.nameField,
            "name1",
            "title",
            "document_name",
            "subject",
            "description",
            "name"
        ];

        for (
            var i = 0;
            i < fields.length;
            i++
        ) {

            var field = fields[i];

            if (
                field &&
                doc[field]
            ) {
                return doc[field];
            }
        }

        return item.name || "Untitled Document";
    }


