    /* =========================================================
       LOAD TAB
    ========================================================= */

    async function loadTab(config) {

        var grid = qs(config.gridId);

        if (!grid) {
            return;
        }

        grid.innerHTML =
            '<div class="fad-loading">' +
            "Loading documents..." +
            "</div>";

        setCount(config.tabKey, 0);


        try {

            var list;

            if (config.useReportView) {

                list = await getReportViewList(
                    config
                );

            } else {

                list = await getClientList(
                    config
                );
            }


            if (!list || !list.length) {

                grid.innerHTML =
                    '<div class="fad-empty">' +
                    "No documents found." +
                    "</div>";

                setCount(
                    config.tabKey,
                    0
                );

                return;
            }


            var fullRecords = await Promise.all(

                list.map(
                    async function (item) {

                        var fullDoc =
                            await getFullDoc(
                                config.doctype,
                                item.name
                            );

                        return {
                            item: item,
                            fullDoc: fullDoc
                        };
                    }
                )
            );


            var documents = [];
            var parentCount = 0;


            fullRecords.forEach(
                function (record) {

                    var item = record.item;
                    var doc = record.fullDoc;

                    if (!doc) {
                        return;
                    }


                    var title =
                        getDocumentTitle(
                            doc,
                            config,
                            item
                        );


                    var rows =
                        getChildRows(
                            doc,
                            config.childTable
                        );


                    var hasFile = false;


                    rows.forEach(
                        function (row) {

                            var url =
                                getRowFileUrl(
                                    row
                                );

                            if (!url) {
                                return;
                            }

                            hasFile = true;

                            documents.push({

                                title: title,

                                url: url,

                                date:
                                    formatDateOnly(
                                        doc[
                                            config.dateField
                                        ] ||
                                        doc.modified ||
                                        item.modified ||
                                        ""
                                    ),

                                icon:
                                    iconMap[
                                        config.tabKey
                                    ] ||
                                    iconMap[
                                        config.doctype
                                    ] ||
                                    "📄"

                            });
                        }
                    );


                    if (hasFile) {
                        parentCount++;
                    }

                }
            );


            renderCards(
                grid,
                documents
            );


            setCount(
                config.tabKey,
                parentCount
            );


            ("[Forms & Documents]", config.doctype, "Parents:", parentCount, "Files:", documents.length, void 0);

        } catch (error) {

            ("[Forms & Documents] Load error", config.doctype, error, void 0);

            grid.innerHTML =
                '<div class="fad-error">' +
                "Unable to load documents." +
                "</div>";

            setCount(
                config.tabKey,
                0
            );
        }
    }


